using System.Security.Cryptography;using System.Text.Json;using AfriWallet.Compliance.ReleaseCandidate.Models;
namespace AfriWallet.Compliance.ReleaseCandidate.Services;
public sealed class RcPackageBuilder
{
    public async Task BuildAsync(string root,RcReport report,CancellationToken ct=default){var release=Path.Combine(root,"release","compliance-platform","v1.6.0-rc1");foreach(var dir in new[]{"runbooks","evidence","configuration","rollback","artifacts"})Directory.CreateDirectory(Path.Combine(release,dir));var payload=new{generatedAtUtc=DateTimeOffset.UtcNow,total=report.Total,passed=report.Passed,failed=report.Failed,skipped=report.Skipped,decision=report.Ready?"READY FOR COMPLIANCE RC":"NOT READY",checks=report.Checks};await File.WriteAllTextAsync(Path.Combine(release,"validation-report.json"),JsonSerializer.Serialize(payload,new JsonSerializerOptions{WriteIndented=true}),ct);await File.WriteAllTextAsync(Path.Combine(release,"validation-report.md"),$"# Compliance RC Validation Report\n\nChecks: {report.Total}\nPassed: {report.Passed}\nFailed: {report.Failed}\nSkipped: {report.Skipped}\n\nDecision: {(report.Ready?"READY FOR COMPLIANCE RC":"NOT READY")}\n",ct);await File.WriteAllLinesAsync(Path.Combine(release,"delivery-tags.txt"),report.Checks.Where(x=>x.Code.StartsWith("sprint16-dlv-",StringComparison.OrdinalIgnoreCase)).Select(x=>$"{x.Code}  {x.Evidence}"),ct);await WriteManifest(release,ct);}
    private static async Task WriteManifest(string release,CancellationToken ct){var manifest=Path.Combine(release,"manifest.sha256");var lines=new List<string>();foreach(var file in Directory.EnumerateFiles(release,"*",SearchOption.AllDirectories).Where(x=>!string.Equals(x,manifest,StringComparison.OrdinalIgnoreCase)).OrderBy(x=>x)){await using var stream=File.OpenRead(file);var hash=await SHA256.HashDataAsync(stream,ct);lines.Add($"{Convert.ToHexString(hash).ToLowerInvariant()}  {Path.GetRelativePath(release,file).Replace('\\','/')}");}await File.WriteAllLinesAsync(manifest,lines,ct);}
}